WITH cleaned AS (SELECT id, customer_id, store_id, order_date, status, channel, shipping_fee, DATE_TRUNC('month', order_date) AS order_date_period, COALESCE(channel, 'UNKNOWN') AS channel_filled FROM orders WHERE order_date > DATE '2023-10-09' AND channel IS NOT DISTINCT FROM 'partner') SELECT s.id, s.store_id, s.status, s.channel, s.shipping_fee, x.paid_at FROM cleaned s LEFT JOIN LATERAL (SELECT c.paid_at FROM payments c WHERE c.order_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) x ON TRUE
